1	package chainledger
2	
3	import (
4		"reflect"
5		"slices"
6		"strings"
7		"testing"
8	)
9	
10	func mustRegister(t *testing.T, graph map[string]*Lineage, name string, parents ...string) {
11		t.Helper()
12		if err := Register(graph, Dataset{Name: name}, parents); err != nil {
13			t.Fatalf("Register(%s, %v): %v", name, parents, err)
14		}
15	}
16	
17	func sameStrings(got, want []string) bool {
18		if len(got) != len(want) {
19			return false
20		}
21		for i := range got {
22			if got[i] != want[i] {
23				return false
24			}
25		}
26		return true
27	}
28	
29	func assertEntry(t *testing.T, graph map[string]*Lineage, name string, wantParents, wantChildren []string) {
30		t.Helper()
31		entry, ok := graph[name]
32		if !ok {
33			t.Fatalf("dataset %q missing from graph", name)
34		}
35		if !sameStrings(entry.Parents, wantParents) {
36			t.Errorf("%s parents = %v, want %v", name, entry.Parents, wantParents)
37		}
38		if !sameStrings(entry.Children, wantChildren) {
39			t.Errorf("%s children = %v, want %v", name, entry.Children, wantChildren)
40		}
41	}
42	
43	// Every parent edge must be mirrored by exactly one matching child edge.
44	func assertConsistent(t *testing.T, graph map[string]*Lineage) {
45		t.Helper()
46		for name, entry := range graph {
47			counts := map[string]int{}
48			for _, c := range entry.Children {
49				counts[c]++
50				child, ok := graph[c]
51				if !ok {
52					t.Errorf("%s lists unknown child %s", name, c)
53					continue
54				}
55				if !slices.Contains(child.Parents, name) {
56					t.Errorf("%s is child of %s but has no matching parent edge", c, name)
57				}
58			}
59			for c, n := range counts {
60				if n != 1 {
61					t.Errorf("%s lists child %s %d times", name, c, n)
62				}
63			}
64			for _, p := range entry.Parents {
65				parent, ok := graph[p]
66				if !ok {
67					t.Errorf("%s lists unknown parent %s", name, p)
68					continue
69				}
70				if !slices.Contains(parent.Children, name) {
71					t.Errorf("%s is parent of %s but has no matching child edge", p, name)
72				}
73			}
74		}
75	}
76	
77	func TestRegisterBasicChainAndConsistency(t *testing.T) {
78		graph := map[string]*Lineage{}
79		mustRegister(t, graph, "raw")
80		mustRegister(t, graph, "detail", "raw")
81		mustRegister(t, graph, "summary", "detail")
82	
83		assertEntry(t, graph, "raw", nil, []string{"detail"})
84		assertEntry(t, graph, "detail", []string{"raw"}, []string{"summary"})
85		assertEntry(t, graph, "summary", []string{"detail"}, nil)
86		assertConsistent(t, graph)
87	
88		if got, want := Roots(graph), []string{"raw"}; !reflect.DeepEqual(got, want) {
89			t.Errorf("Roots = %v, want %v", got, want)
90		}
91	}
92	
93	// The scenario from the spec: re-registering detail while still using raw must
94	// succeed even though raw is detail's existing upstream.
95	func TestReregisterKeepsExistingUpstream(t *testing.T) {
96		graph := map[string]*Lineage{}
97		mustRegister(t, graph, "raw")
98		mustRegister(t, graph, "detail", "raw")
99		mustRegister(t, graph, "summary", "detail")
100	
101		mustRegister(t, graph, "detail", "raw")
102		assertEntry(t, graph, "raw", nil, []string{"detail"})
103		assertEntry(t, graph, "detail", []string{"raw"}, []string{"summary"})
104		assertEntry(t, graph, "summary", []string{"detail"}, nil)
105		assertConsistent(t, graph)
106	
107		// Same registration again: still successful, nothing changes.
108		before := snapshot(graph)
109		mustRegister(t, graph, "detail", "raw")
110		if !reflect.DeepEqual(snapshot(graph), before) {
111			t.Fatalf("identical re-registration changed graph: before=%v after=%v", before, snapshot(graph))
112		}
113	}
114	
115	// Pointing raw at summary closes raw -> summary -> detail -> raw.
116	func TestCycleAcrossMultipleLevelsRejected(t *testing.T) {
117		graph := map[string]*Lineage{}
118		mustRegister(t, graph, "raw")
119		mustRegister(t, graph, "detail", "raw")
120		mustRegister(t, graph, "summary", "detail")
121	
122		before := snapshot(graph)
123		err := Register(graph, Dataset{Name: "raw"}, []string{"summary"})
124		if err == nil {
125			t.Fatal("expected cycle error, got nil")
126		}
127		if !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "summary") {
128			t.Errorf("error %q should mention a cycle and the related name summary", err.Error())
129		}
130		if !reflect.DeepEqual(snapshot(graph), before) {
131			t.Fatalf("failed registration changed graph: before=%v after=%v", before, snapshot(graph))
132		}
133		assertEntry(t, graph, "raw", nil, []string{"detail"})
134		assertConsistent(t, graph)
135	}
136	
137	// Multiple upstreams plus a diamond shape are legitimate and must not look like
138	// a cycle, while a genuinely cyclic multi-parent request is refused.
139	func TestMultipleUpstreamsAndDiamond(t *testing.T) {
140		graph := map[string]*Lineage{}
141		mustRegister(t, graph, "x")
142		mustRegister(t, graph, "y")
143		mustRegister(t, graph, "a", "x")
144		mustRegister(t, graph, "b", "x", "y")
145		mustRegister(t, graph, "d", "a", "b")
146		assertConsistent(t, graph)
147		assertEntry(t, graph, "x", nil, []string{"a", "b"})
148		assertEntry(t, graph, "y", nil, []string{"b"})
149		assertEntry(t, graph, "d", []string{"a", "b"}, nil)
150	
151		// x -> d closes through both a and b, several levels deep.
152		before := snapshot(graph)
153		if err := Register(graph, Dataset{Name: "x"}, []string{"d"}); err == nil {
154			t.Fatal("expected transitive cycle through diamond to be rejected")
155		} else if !strings.Contains(err.Error(), "d") {
156			t.Errorf("error %q should name parent d", err.Error())
157		}
158		if !reflect.DeepEqual(snapshot(graph), before) {
