412	func assertImpact(t *testing.T, impacts []Impact, name string, wantDistance int, wantPath []string) {
413		t.Helper()
414		for _, im := range impacts {
415			if im.Dataset != name {
416				continue
417			}
418			if im.Distance != wantDistance {
419				t.Errorf("impact %s distance = %d, want %d", name, im.Distance, wantDistance)
420			}
421			if !sameStrings(im.Path, wantPath) {
422				t.Errorf("impact %s path = %v, want %v", name, im.Path, wantPath)
423			}
424			return
425		}
426		t.Fatalf("impact %q missing from %v", name, impactNames(impacts))
427	}
