500	// Among multiple shortest paths the lexicographically smallest full name
501	// sequence wins, compared name by name in Go string order, even when child list
502	// order would suggest otherwise.
503	func TestImpactsLexicographicallySmallestShortestPath(t *testing.T) {
504		graph := map[string]*Lineage{}
505		mustRegister(t, graph, "s")
506		// Register the lexicographically larger branch first so stored child order
507		// disagrees with the expected path choice.
508		mustRegister(t, graph, "z", "s")
509		mustRegister(t, graph, "a", "s")
510		mustRegister(t, graph, "m", "z", "a")
511	
512		impacts, err := Impacts(graph, "s")
513		if err != nil {
514			t.Fatalf("Impacts(s): %v", err)
515		}
516		assertImpact(t, impacts, "m", 2, []string{"s", "a", "m"})
517	
518		// Tie decided at the final hop: both x routes to n have equal length.
519		mustRegister(t, graph, "x1", "s")
520		mustRegister(t, graph, "x2", "s")
521		mustRegister(t, graph, "n", "x2", "x1")
522		impacts, err = Impacts(graph, "s")
523		if err != nil {
524			t.Fatalf("Impacts(s): %v", err)
525		}
526		assertImpact(t, impacts, "n", 2, []string{"s", "x1", "n"})
527	
528		// A longer-looking but lexicographically smaller route must not replace a
529		// genuinely shorter path: distance takes priority. q joins at distance 2 via
530		// z, and at distance 3 via a -> m.
531		mustRegister(t, graph, "q", "m", "z")
532		impacts, err = Impacts(graph, "s")
533		if err != nil {
534			t.Fatalf("Impacts(s): %v", err)
535		}
536		assertImpact(t, impacts, "q", 2, []string{"s", "z", "q"})
537	}
