689	type snap struct {
690		parents  map[string][]string
691		children map[string][]string
692	}
693	
694	func snapshot(graph map[string]*Lineage) snap {
695		s := snap{map[string][]string{}, map[string][]string{}}
696		for name, e := range graph {
697			s.parents[name] = append([]string(nil), e.Parents...)
698			s.children[name] = append([]string(nil), e.Children...)
699		}
700		return s
701	}
